<?php require_once __DIR__ . '/../includes/bootstrap.php';$user=require_login('seeker');$s=database()->prepare('SELECT qa.*,j.title,j.id job_id FROM quiz_attempts qa JOIN jobs j ON j.id=qa.job_id WHERE qa.id=? AND qa.seeker_id=?');$s->execute([(int)($_GET['id']??0),$user['id']]);$a=$s->fetch();if(!$a)exit('Result not found.');page_header('Quiz result'); ?><article class="card"><h1><?= $a['passed'] ? 'You passed' : 'Keep preparing' ?></h1><p class="lead">Score: <?=e($a['percentage'])?>% (<?=e($a['score'])?> / <?=e($a['total_marks'])?> marks)</p><?php if($a['passed']):?><p>You may now apply for <?=e($a['title'])?>.</p><a class="button" href="applications.php?job_id=<?=$a['job_id']?>">Apply for this role</a><?php else:?><p>These courses are recommended based on the skills associated with this job. Completing them may help you prepare for another attempt.</p><a class="button" href="recommendations.php?job_id=<?=$a['job_id']?>">View recommended courses</a><?php endif;?></article><?php page_footer(); ?>